package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

const MOD int64 = 998244353

func modFunc(num int64) int64 {
	if num >= MOD {
		return num % MOD
	} else if num < 0 {
		return (num%MOD + MOD) % MOD
	}
	return num
}

func mul(args ...int64) int64 {
	if len(args) == 0 {
		panic("参数不能为空")
	}
	if len(args) == 1 {
		return args[0]
	}
	a, b := args[0], args[1]
	if len(args) > 2 {
		rest := append([]int64{mul(a, b)}, args[2:]...)
		return mul(rest...)
	}
	return (a/65536*b%MOD*65536 + (a&65535)*b) % MOD
}

func getPrimes(n int64) []int64 {
	nums := make([]int64, n+1)
	for i := range nums {
		nums[i] = 1
	}
	nums[0] = 0
	if n >= 1 {
		nums[1] = 0
	}
	primes := []int64{}
	for i := int64(2); i <= n; i++ {
		if nums[i] == 1 {
			primes = append(primes, i)
		}
		for j := 0; j < len(primes) && primes[j] <= n/i; j++ {
			nums[primes[j]*i] = 0
			if i%primes[j] == 0 {
				break
			}
		}
	}
	return nums
}

func solve(read func() string) int64 {
	line := read()
	parts := strings.Fields(line)
	n, _ := strconv.ParseInt(parts[0], 10, 64)
	m, _ := strconv.ParseInt(parts[1], 10, 64)

	var pre int64 = 1
	M := modFunc(m)
	var res int64 = 0
	ans := M
	ans1 := M
	p := getPrimes(n + 10)
	for i := int64(2); i <= n; i++ {
		if pre <= m && p[i] == 1 {
			pre = pre * i
		}
		if pre > m {
			ans = 0
		} else {
			ans = mul(ans, m/pre)
		}
		ans1 = mul(ans1, M)
		res = modFunc(res + ans1 - ans)
	}
	return res
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	scanner := bufio.NewScanner(reader)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
	var lines []string
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	idx := 0
	read := func() string {
		line := lines[idx]
		idx++
		return line
	}
	res := solve(read)
	fmt.Print(res)
}
